1	import { useRef, useState, useEffect, useMemo } from 'react'
2	import { useVirtualizer } from '@tanstack/react-virtual'
3	import { DndContext, DragOverlay, PointerSensor, closestCenter, useSensor, useSensors } from '@dnd-kit/core'
4	import type { DragEndEvent } from '@dnd-kit/core'
5	import { SortableContext, useSortable, verticalListSortingStrategy } from '@dnd-kit/sortable'
6	import { CSS } from '@dnd-kit/utilities'
7	import * as pageCache from '../../lib/pageCache'
8	import { makeResizeDragHandler } from '../../lib/resizableWidth'
9	import { DEFAULT_WIDTH, ITEM_PADDING, PAGE_ASPECT, LABEL_HEIGHT, HEADER_HEIGHT } from '../../constants'
10	import PageThumbnail from '../PageThumbnail'
11	import ResizeHandle from '../ResizeHandle'
12	import type { OutputFilesHandle } from './useOutputFiles'
13	import OutputFileHeader from './OutputFileHeader'
14	import type { PendingFocusHandle } from './usePendingFocus'
15	import styles from './ThumbnailPanel.module.css'
16	
17	const MIN_WIDTH = 120
18	const MAX_WIDTH = 480
19	const GAP_HEIGHT = 16
20	
21	type ListItem =
22	  | { type: 'header'; fileIndex: number; firstPosition: number }
23	  | { type: 'page'; page: number; position: number }
24	
25	function buildItems(pageOrder: number[], splitPoints: Set<number>): ListItem[] {
26	  const result: ListItem[] = []
27	  let fileIndex = 0
28	  for (let pos = 0; pos < pageOrder.length; pos++) {
29	    if (pos === 0 || splitPoints.has(pos - 1)) {
30	      result.push({ type: 'header', fileIndex: fileIndex++, firstPosition: pos })
31	    }
32	    result.push({ type: 'page', page: pageOrder[pos], position: pos })
33	  }
34	  return result
35	}
36	
37	interface Props {
38	  pdfPath: string
39	  pageOrder: number[]
40	  selectedPage: number
41	  onSelectPage: (page: number) => void
42	  onToggleSplitPoint: (afterPosition: number) => void
43	  outputFiles: OutputFilesHandle
44	  outputFolder: string | null
45	  focus: PendingFocusHandle
46	  rotations: Map<number, number>
47	  onRotate: (page: number) => void
48	  skipped: Set<number>
49	  onToggleSkip: (page: number) => void
50	  onMovePage: (fromPos: number, toPos: number) => void
51	}
52	
53	export default function SplitThumbnailPanel({
54	  pdfPath, pageOrder, selectedPage, onSelectPage,
55	  onToggleSplitPoint,
56	  outputFiles,
57	  outputFolder,
58	  focus,
59	  rotations,
60	  onRotate,
61	  skipped,
62	  onToggleSkip,
63	  onMovePage,
64	}: Props) {
65	  const [panelWidth, setPanelWidth] = useState(DEFAULT_WIDTH)
66	  const startDrag = makeResizeDragHandler(panelWidth, setPanelWidth, MIN_WIDTH, MAX_WIDTH)
67	  const [hoveredGap, setHoveredGap] = useState<number | null>(null)
68	  const [hoveredPage, setHoveredPage] = useState<number | null>(null)
69	  const [activeId, setActiveId] = useState<number | null>(null)
70	  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 8 } }))
71	
72	  const thumbWidth = panelWidth - ITEM_PADDING * 2
73	  const thumbHeight = Math.round(thumbWidth * PAGE_ASPECT)
74	  const pageItemHeight = thumbHeight + LABEL_HEIGHT + ITEM_PADDING + GAP_HEIGHT
75	
76	  const splitPoints = useMemo(() => outputFiles.getSplitPoints(), [outputFiles.all])
77	  const items = useMemo(() => buildItems(pageOrder, splitPoints), [pageOrder, splitPoints])
78	  // Ref so the scroll effect can read the current list without depending on it
79	  // (we don't want to re-scroll every time a split point is toggled).
80	  const itemsRef = useRef(items)
81	  itemsRef.current = items
82	
83	  const scrollRef = useRef<HTMLDivElement>(null)
84	
85	  const virtualizer = useVirtualizer({
86	    count: items.length,
87	    getScrollElement: () => scrollRef.current,
88	    estimateSize: (index) => items[index]?.type === 'header' ? HEADER_HEIGHT : pageItemHeight,
89	    overscan: 3,
90	  })
91	
92	  useEffect(() => {
93	    virtualizer.measure()
94	    // eslint-disable-next-line react-hooks/exhaustive-deps
95	  }, [items.length, pageItemHeight])
96	
97	  const virtualItems = virtualizer.getVirtualItems()
98	  pageCache.usePageCacheRender()
99	
100	  // Keyed on the visible range (not virtualItems itself, which is a fresh array every
101	  // render) so this only re-runs when scroll position, data, or sizing actually change —
102	  // not on unrelated re-renders like hover state.
103	  useEffect(() => {
104	    for (const vItem of virtualItems) {
105	      const item = items[vItem.index]
106	      if (item.type === 'page') pageCache.load(pdfPath, item.page, thumbWidth)
107	    }
108	    // eslint-disable-next-line react-hooks/exhaustive-deps
109	  }, [virtualizer.range?.startIndex, virtualizer.range?.endIndex, items, pdfPath, thumbWidth])
110	
111	  useEffect(() => {
112	    const index = itemsRef.current.findIndex(item => item.type === 'page' && item.page === selectedPage)
113	    if (index >= 0) virtualizer.scrollToIndex(index, { align: 'auto' })
114	    // eslint-disable-next-line react-hooks/exhaustive-deps
115	  }, [selectedPage])
116	
117	  useEffect(() => {
118	    const handler = (e: KeyboardEvent) => {
119	      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
120	      const selectedPos = pageOrder.indexOf(selectedPage)
121	      if (e.key === 'ArrowLeft') {
122	        e.preventDefault()
123	        if (selectedPos > 0) onSelectPage(pageOrder[selectedPos - 1])
124	      } else if (e.key === 'ArrowRight') {
125	        e.preventDefault()
126	        if (selectedPos < pageOrder.length - 1) onSelectPage(pageOrder[selectedPos + 1])
127	      } else if (e.key === 'Delete' || e.key === 'Backspace') {
128	        e.preventDefault()
129	        onToggleSkip(selectedPage)
130	      }
131	    }
132	    window.addEventListener('keydown', handler)
133	    return () => window.removeEventListener('keydown', handler)
134	  }, [selectedPage, pageOrder, onSelectPage, onToggleSkip])
135	
136	  const handleDragEnd = ({ active, over }: DragEndEvent) => {
137	    setActiveId(null)
138	    if (!over || active.id === over.id) return
139	    const fromPos = pageOrder.indexOf(active.id as number)
140	    const toPos = pageOrder.indexOf(over.id as number)
141	    if (fromPos !== -1 && toPos !== -1) onMovePage(fromPos, toPos)
142	  }
143	
144	  return (
145	    <div className={styles.outer}>
146	      <div className={styles.panel} style={{ width: panelWidth }}>
147	        <DndContext
148	          sensors={sensors}
149	          collisionDetection={closestCenter}
150	          onDragStart={({ active }) => setActiveId(active.id as number)}
151	          onDragEnd={handleDragEnd}
152	        >
153	          <SortableContext items={pageOrder} strategy={verticalListSortingStrategy}>
154	            <div ref={scrollRef} className={styles.scroll}>
155	              <div className={styles.sizer} style={{ height: virtualizer.getTotalSize() }}>
156	                {virtualItems.map(vItem => {
157	                  const item = items[vItem.index]
158	
159	                  if (item.type === 'header') {
160	                    return (
161	                      <div
162	                        key={vItem.key}
163	                        className={styles.headerWrapper}
164	                        style={{ top: vItem.start, height: vItem.size }}
165	                      >
166	                        <OutputFileHeader
167	                          filename={outputFiles.all.get(item.firstPosition)?.name ?? ''}
168	                          onChange={(name) => outputFiles.setName(item.firstPosition, name)}
169	                          firstPosition={item.firstPosition}
170	                          focus={focus}
171	                          folder={outputFiles.all.get(item.firstPosition)?.folderOverride ?? outputFolder}
